// Canopy-density rasters read straight off the summer ArcGIS aerials.
// Value = fraction of the cell classified as conifer canopy (dark AND
// green-dominant), 0..255. aerial.jpg is exactly 1000.0 m across at
// 0.48828 m/px; aerial-2.jpg is exactly 3200.0 m and shares its bbox with
// dem-wide.tif, so both register 1:1 with the DEM with no eyeballing.
// This is what places the forest: the tree striping IS the aerial's striping.
export const CAN_TIGHT = { span: 1000.0, n: 512, ox: -0.00, oy: 0.00, b64: "" };
export const CAN_WIDE = { span: 3200.0, n: 512, ox: -251.93, oy: -274.95, b64: "" };
